import { Signal } from '@angular/core';
import type { DialogEvent } from './types';

export interface SubscriptionLike {
    unsubscribe(): void;
}

export interface Subscribable<T> {
    subscribe(next: (value: T) => void): SubscriptionLike | (() => void);
}

function disposeSubscription(subscription: SubscriptionLike | (() => void)) {
    if (typeof subscription === 'function') {
        subscription();
    } else {
        subscription.unsubscribe();
    }
}

export function waitForEvent<T>(
    source: Subscribable<T>,
    predicate: (value: T) => boolean = () => true,
): Promise<T> {
    return new Promise<T>((resolve) => {
        let subscription: SubscriptionLike | (() => void) | null = null;
        let should_dispose = false;
        subscription = source.subscribe((value) => {
            if (!predicate(value)) return;
            if (subscription) {
                disposeSubscription(subscription);
            } else {
                should_dispose = true;
            }
            resolve(value);
        });
        if (should_dispose && subscription) disposeSubscription(subscription);
    });
}

/**
 * Resolves with the first value of the signal that passes the predicate.
 * Checks every `delay` ms, and rejects after `max_wait` ms so a value that
 * never arrives cannot leave the caller waiting forever.
 */
export function waitForSignalValue<T>(
    source: Signal<T>,
    predicate: (value: T) => boolean = () => true,
    delay = 50,
    max_wait = 60 * 1000,
): Promise<T> {
    return new Promise<T>((resolve, reject) => {
        const started = Date.now();
        const check = () => {
            const value = source();
            if (predicate(value)) return resolve(value);
            if (Date.now() - started >= max_wait) {
                return reject(new Error('Timed out waiting for signal value'));
            }
            setTimeout(check, delay);
        };
        check();
    });
}

/**
 * Wait until a dialog emits an event with the given `reason`, or closes.
 * Resolves to that event, or to the close result when the dialog closes first.
 */
export function waitForDialog<T = unknown>(
    ref: {
        componentInstance: { event: Subscribable<DialogEvent> };
        closed: Subscribable<unknown>;
    },
    reason: DialogEvent['reason'],
): Promise<DialogEvent<T> | undefined> {
    return Promise.race([
        waitForEvent(ref.componentInstance.event, (e) => e.reason === reason),
        waitForEvent(ref.closed),
    ]) as Promise<DialogEvent<T> | undefined>;
}
